  (university_id,name,slug,field,qualification,degree_type,duration,
   programme_url,source_url,primary_source_url,source_urls,source_tier,
   verification_status,verified,needs_review,verification_method,verification_notes,
   notes,field_sources)
SELECT 'e4e157e7-c4c3-48cd-9b2f-87a9e235137f'::uuid, c.name, c.slug, c.field, c.qualification, c.degree_type, c.duration,
       c.source_url, c.source_url, c.source_url, ARRAY[c.source_url],
       'official_institution_catalogue',
       'source_linked_needs_individual_review', false, true,
       'Official institution programme catalogue listing',
       'Source listing confirms the programme title and award label; per-programme detail and current admission availability still require individual review.',
       'Seeded from the University of Ghana International Programmes Office catalogue listing. Unverified until independently reviewed.',
